<script setup>
import {ref,computed,onMounted} from 'vue'
import {call} from './service'
import Icon from './Icon.vue'
const period=ref('month'),data=ref(null),metric=ref('students')
const max=computed(()=>Math.max(1,...(data.value?.buckets||[]).map(b=>b[metric.value])))
const money=(n,c)=>new Intl.NumberFormat('en',{style:'currency',currency:c,maximumFractionDigits:0}).format(n)
async function refresh(){data.value=await call('platform_summary',{period:period.value})}
onMounted(refresh)
</script>
<template><div class="page-heading"><div><div class="eyebrow">PLATFORM OWNER · THE BIGGER PICTURE</div><h1>Your learning platform, growing.</h1><p>Registered accounts, education providers and payment activity across the demo network.</p></div><label class="compact-filter">Reporting period<select v-model="period" @change="refresh"><option value="week">This week</option><option value="month">This month</option><option value="year">This year</option></select></label></div><template v-if="data"><section class="owner-banner"><span class="stat-icon white"><Icon name="Building2" :size="30"/></span><div><span class="eyebrow">ONE PLATFORM. MANY LEARNING COMMUNITIES.</span><h2>A clear view of every next chapter.</h2><p>{{data.from}} to {{data.to}} · Aggregate demo reporting</p></div><span class="badge white">Platform Owner</span></section><div class="insight-stats"><div><span class="stat-icon violet"><Icon name="Users"/></span><strong>{{data.studentCount}}</strong><small>Registered student accounts · {{data.newStudents}} new this period</small></div><div><span class="stat-icon peach"><Icon name="GraduationCap"/></span><strong>{{data.teacherCount}}</strong><small>Registered teacher accounts · {{data.newTeachers}} new this period</small></div><div><span class="stat-icon mint"><Icon name="Building2"/></span><strong>{{data.instituteCount}}</strong><small>Institute profiles · {{data.independentCount}} independent teacher profiles</small></div><div><span class="stat-icon violet"><Icon name="Receipt"/></span><strong>{{data.transactions.length.toLocaleString()}}</strong><small>Settled transactions in this period</small></div></div><div class="insight-grid"><section class="panel"><div class="section-heading"><div><h2>Growth over time</h2><p>{{metric==='students'?'New student registrations':'Settled transaction count'}}</p></div><select v-model="metric" aria-label="Growth chart metric"><option value="students">Registrations</option><option value="transactions">Transactions</option></select></div><div class="owner-chart" :class="{daily:period==='month'}"><div v-for="b in data.buckets" :key="b.key" :title="b.key+': '+b[metric]"><span>{{b[metric]}}</span><div><i :style="{height:Math.max(1,b[metric]/max*100)+'%'}"></i></div><small>{{b.label}}</small></div></div><p class="field-help">Account totals count actual demo members. Public provider profiles are listed separately and do not imply additional registered accounts.</p></section><section class="panel"><div class="section-heading"><h2>Payment activity by currency</h2><Icon name="Wallet"/></div><div v-for="(amount,currency) in data.currencies" class="owner-money"><span>{{currency}}</span><strong>{{money(amount,currency)}}</strong></div><p v-if="!Object.keys(data.currencies).length">No settled payments in this period.</p><p class="field-help">These are tuition collections represented by demo invoices, not platform earnings. Subscription revenue, gateway fees and refunds require their own reconciled ledgers. No currency conversion is applied.</p><div class="form-note"><Icon name="ShieldCheck"/><span>Institute Admin manages one institute. Platform Owner receives aggregate network reporting.</span></div></section></div><section class="panel"><div class="section-heading"><h2>Your education network</h2><span class="count-pill">{{data.providers.length}} provider profiles</span></div><div class="table-wrap"><table><thead><tr><th>Provider</th><th>Code</th><th>Type</th><th>Country</th></tr></thead><tbody><tr v-for="p in data.providers"><td><strong>{{p.title}}</strong></td><td>{{p.code}}</td><td>{{p.type}}</td><td>{{p.country}}</td></tr></tbody></table></div></section><section class="panel owner-transactions"><div class="section-heading"><h2>Recent payment references</h2><span class="badge violet">Latest 20 in selected period</span></div><div class="table-wrap"><table><thead><tr><th>Reference</th><th>Provider</th><th>Date</th><th>Amount</th><th>Status</th></tr></thead><tbody><tr v-for="t in data.transactions.slice(0,20)"><td>{{t.reference}}</td><td>{{t.provider}}</td><td>{{t.date}}</td><td>{{money(t.amount,t.currency)}}</td><td><span class="badge green">Settled · demo</span></td></tr></tbody></table></div></section></template></template>
